import io

import jq


def compile_status(program: str) -> tuple[int, str]:
    output = io.StringIO()
    status = jq.run(["-c", program], io.StringIO("null\n"), output)
    return status, output.getvalue()


def test_unterminated_program_is_rejected_before_evaluation() -> None:
    assert compile_status("{") == (3, "")


def test_undefined_binding_is_rejected_before_evaluation() -> None:
    assert compile_status(". as $known | $unknown") == (3, "")


def test_constant_non_string_object_key_is_rejected() -> None:
    assert compile_status("{(0):1}") == (3, "")


def test_unresolved_break_label_is_rejected() -> None:
    assert compile_status(". as $foo | break $foo") == (3, "")


def test_valid_program_reaches_evaluation() -> None:
    output = io.StringIO()
    status = jq.run(["-c", "."], io.StringIO('{"valid":[1,2]}\n'), output)
    assert status == 0
    assert output.getvalue() == '{"valid":[1,2]}\n'

import io
import json

import jq


def run_filter(program: str, payload: object) -> tuple[int, list[object]]:
    output = io.StringIO()
    status = jq.run(["-c", program], io.StringIO(json.dumps(payload) + "\n"), output)
    return status, [json.loads(line) for line in output.getvalue().splitlines()]


def test_parser_precedence_executes_grouped_arithmetic() -> None:
    assert run_filter("(1 + 2) * 3", None) == (0, [9])


def test_parser_constructs_nested_array_and_object() -> None:
    payload = {"x": 1}
    assert run_filter("{value: ., items: [., 2]}", payload) == (0, [{"value": payload, "items": [payload, 2]}])


def test_parser_rejects_unterminated_object() -> None:
    assert run_filter("{a: 1", None)[0] == 3


def test_parser_supports_pipe_and_field_indexing() -> None:
    assert run_filter(".items[] | .name", {"items": [{"name": "a"}, {"name": "b"}]}) == (0, ["a", "b"])


def test_parser_supports_conditional() -> None:
    assert run_filter('if . > 1 then "large" else "small" end', 2) == (0, ["large"])

